const kmPerDegreeLat = 111.32
const earthCircumferenceKm = 40075.016686
const round = (value: number) => Math.round(value * 10) / 10
// Web Mercator's northing of a latitude, the projection the map lines come in.
const mercatorY = (latitude: number) => Math.log(Math.tan(Math.PI / 4 + latitude * Math.PI / 360))

type Theme = {
  name: string
  page: string
  radar: string
  grid: string
  text: string
  muted: string
  accent: string
  plane: string
  planeStroke: string
  planeLabel: string
  card: string
  border: string
  // The map under the radar: water, its shore and rivers, roads and highways.
  water: string
  shore: string
  road: string
  highway: string
}

