type MapLines = {
  water: any[]
  rivers: any[]
  roads: any[]
  borders: any[]
  towns: any[]
  attribution: string
}

type Aircraft = {
  callsign: string
  xKm: number
  yKm: number
  distance: number
  track: number
  altitudeFt: number | null
  speedKts: number | null
  origin?: string
  destination?: string
  airline?: string
  country?: string
}

function toAircraft(row: any[], latitude: number, longitude: number, radiusKm: number): Aircraft | null {
  const longitudeValue = Number(row[5])
  const latitudeValue = Number(row[6])
  if (!Number.isFinite(latitudeValue) || !Number.isFinite(longitudeValue) || row[8]) return null
  const cosLatitude = Math.cos(latitude * Math.PI / 180)
  const xKm = (longitudeValue - longitude) * kmPerDegreeLat * cosLatitude
  const distance = Math.hypot(xKm, (latitudeValue - latitude) * kmPerDegreeLat)
  if (distance > radiusKm) return null
  // North of the center in the map's projection, at the center's scale, so planes sit on the map lines.
  const yKm = (mercatorY(latitudeValue) - mercatorY(latitude)) * earthCircumferenceKm / (2 * Math.PI) * cosLatitude
  const altitudeM = Number(row[7])
  const speedMs = Number(row[9])
  return {
    callsign: String(row[1] || row[0] || "Unknown").trim(),
    xKm,
    yKm,
    distance,
    track: Number.isFinite(Number(row[10])) ? Number(row[10]) : 0,
    altitudeFt: Number.isFinite(altitudeM) ? Math.round(altitudeM * 3.28084 / 100) * 100 : null,
    speedKts: Number.isFinite(speedMs) ? Math.round(speedMs * 1.94384) : null,
    country: String(row[2] || "").trim() || undefined
  }
}

function routeFor(callsign: string, cache: Record<string, any>, budget: { left: number; changed: boolean }) {
  const key = callsign.toUpperCase().replace(/\s+/g, "")
  const saved = cache[key]
  if (saved && saved.until > Date.now()) return saved.value
  if (!key || budget.left <= 0) return saved?.value || {}
  budget.left -= 1
  let value: Record<string, string> = {}
  try {
    const result = frameos.httpRequest(`https://api.adsbdb.com/v0/callsign/${encodeURIComponent(key)}`, { timeoutMs: 4500 })
    const route = result.status === 200 && result.body ? JSON.parse(result.body)?.response?.flightroute : null
    const origin = route?.origin?.iata_code || route?.origin?.icao_code
    const destination = route?.destination?.iata_code || route?.destination?.icao_code
    const airline = route?.airline?.name || route?.airline?.iata
    if (origin && destination) value = { origin: String(origin), destination: String(destination), airline: airline ? String(airline) : "" }
  } catch (_) {}
  cache[key] = { value, until: Date.now() + (Object.keys(value).length ? 14400000 : 3600000) }
  budget.changed = true
  return value
}

// The radar circle's radius in pixels: the same for the map request and the drawing.
const radarRadius = (size: number) => size / 2 - size * 0.045

// Lines from maps.frameos.net (OpenStreetMap) for the radar's square, already in its pixels:
// the zoom puts radiusKm on the radar circle. Null when the service does not answer. The radar
// needs little of a map: `maxKb` caps the answer and the service drops detail to fit.
function fetchMap(latitude: number, longitude: number, radiusKm: number, size: number, withTowns: boolean, townSize: number, maxKb: number): MapLines | null {
  const pixelsPerKm = radarRadius(size) / radiusKm
  const zoom = Math.log2(pixelsPerKm * earthCircumferenceKm * Math.cos(latitude * Math.PI / 180) / 256)
  // The service picks roads and rivers by the zoom, so a bigger radar would get ever more of them:
  // ask for what a 480-pixel radar shows, drawn sharper.
  const detail = Math.max(-3, Math.min(0, Math.round(zoom - Math.log2(size / 480)) - Math.round(zoom)))
  const query = [
    `lat=${latitude}`, `lon=${longitude}`, `zoom=${zoom.toFixed(2)}`, `width=${size}`, `height=${size}`, `detail=${detail}`,
    `layers=water,rivers,roads,boundaries${withTowns ? ",places" : ""}`,
    "rivers=river,canal", "roads=major_road,highway", "boundaries=country,disputed",
    withTowns ? `places=locality&labels=24&font=${Math.round(townSize)}` : "", "simplify=1", `maxkb=${maxKb}`
  ]
  const url = `https://maps.frameos.net/v1/lines?${query.filter(Boolean).join("&")}`
  // The service builds a view it has not cached on the fly and can turn the first try away.
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const result = frameos.httpRequest(url, { timeoutMs: 8000 })
      const layers = result.status === 200 && result.body ? JSON.parse(result.body)?.layers : null
      if (layers) {
        return {
          water: layers.water || [],
          rivers: layers.rivers || [],
          roads: layers.roads || [],
          borders: layers.boundaries || [],
          towns: layers.places || [],
          attribution: "© OpenStreetMap contributors"
        }
      }
    } catch (_) {}
  }
  return null
}

// A stroked path is outlined whole before any of it is filled: London's roads as one path took
// 3.5 MB of an ESP32's memory to draw and crashed it, the same roads in 2 KB pieces 0.25 MB.
// The pieces start where a line starts (the service writes an absolute "M" for each), and
// the lines are opaque, so they draw the same.
function strokePieces(d: string): string[] {
  const pieces: string[] = []
  let start = 0
  while (start < d.length) {
    let end = Math.min(d.length, start + 2000)
    if (end < d.length) {
      const next = d.indexOf("M", end)
      end = next < 0 ? d.length : next
    }
    pieces.push(d.slice(start, end))
    start = end
  }
  return pieces
}

// Water, rivers, roads and borders inside the radar circle, with the map's credit in the corner.
function MapLinesUnder({ map, size, theme }: { map: MapLines; size: number; theme: Theme }) {
  const center = size / 2
  const radius = radarRadius(size)
  // The lines run a few pixels past the square, and nothing clips an SVG to its viewBox.
  const margin = Math.max(8, size * 0.02)
  const line = (d: string, color: string, width: number, dash?: string) => <g>
    {strokePieces(d).map((piece) => <path d={piece} fill="none" stroke={color} strokeWidth={width} strokeDasharray={dash} strokeLinecap="round" strokeLinejoin="round" />)}
  </g>
  return <g>
    {map.water.map((area) => <path d={area.fill} fill={theme.water} />)}
    {map.water.map((area) => line(area.stroke, theme.shore, Math.max(0.8, size * 0.0022)))}
    {map.rivers.map((river) => line(river.d, theme.shore, Math.max(0.8, size * 0.0024)))}
    {map.roads.filter((road) => road.kind !== "highway").map((road) => line(road.d, theme.road, Math.max(0.8, size * 0.0019)))}
    {map.roads.filter((road) => road.kind === "highway").map((road) => line(road.d, theme.highway, Math.max(1.1, size * 0.0032)))}
    {map.borders.map((border) => line(border.d, theme.muted, Math.max(0.8, size * 0.002), "6 4"))}
    {/* Outside the circle: the page again, over whatever the map drew there. */}
    <path d={`M${-margin} ${-margin}H${size + margin}V${size + margin}H${-margin}Z M${center - radius} ${center}A${radius} ${radius} 0 1 0 ${center + radius} ${center}A${radius} ${radius} 0 1 0 ${center - radius} ${center}Z`} fill={theme.page} fillRule="evenodd" />
    <text x={size - 2} y={size - 3} fontFamily="Ubuntu" fontSize={Math.max(9, size * 0.018)} textAnchor="end" fill={theme.muted} fillOpacity=".8">{map.attribution}</text>
  </g>
}

function TownNames({ map, size, theme, townSize }: { map: MapLines; size: number; theme: Theme; townSize: number }) {
  const center = size / 2
  const marker = Math.max(5, size * 0.015)
  // Names the circle would cut, or the marker in the middle would cover, are left out.
  const towns = map.towns.filter((town) => Math.hypot(town.x - center, town.y - center) < radarRadius(size) - townSize * 1.5
    && (Math.abs(town.x - center) > town.name.length * townSize * 0.28 + marker || Math.abs(town.y - center) > townSize * 0.6 + marker))
  return <g>
    {towns.map((town) => <text x={round(town.x)} y={round(town.y)} fontFamily="Ubuntu" fontSize={townSize} textAnchor="middle" dominantBaseline="middle" fill="none" stroke={theme.radar} strokeWidth={Math.max(2, townSize / 4)} strokeLinejoin="round">{town.name}</text>)}
    {towns.map((town) => <text x={round(town.x)} y={round(town.y)} fontFamily="Ubuntu" fontSize={townSize} textAnchor="middle" dominantBaseline="middle" fill={theme.muted}>{town.name}</text>)}
  </g>
}

function Radar({ aircraft, radiusKm, size, theme, map, townSize }: { aircraft: Aircraft[]; radiusKm: number; size: number; theme: Theme; map: MapLines | null; townSize: number }) {
  const center = size / 2
  const edge = size * 0.045
  const radius = radarRadius(size)
  const scale = radius / radiusKm
  const planeSize = Math.max(10, size * 0.026)
  const labelSize = Math.max(12, size * 0.021)
  const candidates = [[0.72, -0.64], [0.72, 0.7], [-0.72, -0.64], [-0.72, 0.7], [0, -1.02], [0, 1.08], [1.02, 0], [-1.02, 0]]
  const placed: { x: number; y: number }[] = []
  const rings = [0.25, 0.5, 0.75, 1]
  return <svg viewBox={`0 0 ${size} ${size}`} className="size-full" aria-label="Aircraft radar">
    <circle cx={center} cy={center} r={radius} fill={theme.radar} />
    {map ? <MapLinesUnder map={map} size={size} theme={theme} /> : null}
    <circle cx={center} cy={center} r={radius} fill="none" stroke={theme.grid} strokeWidth={Math.max(1, size * 0.003)} />
    {rings.map((fraction) => <circle key={`ring-${fraction}`} cx={center} cy={center} r={radius * fraction} fill="none" stroke={theme.grid} strokeOpacity=".52" strokeWidth={Math.max(1, size * 0.002)} />)}
    <line x1={center} y1={edge} x2={center} y2={size - edge} stroke={theme.grid} strokeOpacity=".52" strokeWidth={Math.max(1, size * 0.002)} />
    <line x1={edge} y1={center} x2={size - edge} y2={center} stroke={theme.grid} strokeOpacity=".52" strokeWidth={Math.max(1, size * 0.002)} />
    {map ? <TownNames map={map} size={size} theme={theme} townSize={townSize} /> : null}
    {rings.map((fraction) => {
      const ringRadius = radius * fraction
      const angle = -Math.PI / 4
      const x = center + ringRadius * Math.cos(angle)
      const y = center + ringRadius * Math.sin(angle)
      return <text key={`distance-${fraction}`} x={round(x + size * 0.018)} y={round(y - size * 0.012)} fontFamily="Ubuntu" fontSize={Math.max(11, size * 0.024)} fill={theme.muted}>{Math.round(radiusKm * fraction)} km</text>
    })}
    <text x={center} y={edge + size * 0.035} fontFamily="Ubuntu" fontSize={Math.max(13, size * 0.034)} textAnchor="middle" fill={theme.muted}>N</text>
    <circle cx={center} cy={center} r={Math.max(5, size * 0.015)} fill={theme.accent} stroke={theme.text} strokeWidth={Math.max(1, size * 0.003)} />
    {aircraft.map((plane, index) => {
      const x = center + plane.xKm * scale
      const y = center - plane.yKm * scale
      let chosen = candidates[index % candidates.length]
      for (const candidate of candidates) {
        const testX = x + candidate[0] * planeSize
        const testY = y + candidate[1] * planeSize
        if (!placed.some((item) => Math.abs(item.x - testX) < labelSize * 4.8 && Math.abs(item.y - testY) < labelSize * 1.5)) {
          chosen = candidate
          break
        }
      }
      const labelX = x + chosen[0] * planeSize
      const labelY = y + chosen[1] * planeSize
      const anchor = chosen[0] < -0.2 ? "end" : chosen[0] > 0.2 ? "start" : "middle"
      placed.push({ x: labelX, y: labelY })
      return <g key={`${plane.callsign}-${index}`}>
        <g transform={`translate(${round(x)} ${round(y)}) rotate(${round(plane.track)})`}>
          <path d={`M 0 ${-planeSize * 0.78} L ${planeSize * 0.2} ${-planeSize * 0.13} L ${planeSize * 0.62} ${planeSize * 0.5} L ${planeSize * 0.16} ${planeSize * 0.35} L 0 ${planeSize * 0.75} L ${-planeSize * 0.16} ${planeSize * 0.35} L ${-planeSize * 0.62} ${planeSize * 0.5} L ${-planeSize * 0.2} ${-planeSize * 0.13} Z`} fill={theme.plane} stroke={theme.planeStroke} strokeWidth={Math.max(1, size * 0.0025)} strokeLinejoin="round" />
        </g>
        <text x={round(labelX)} y={round(labelY)} fontFamily="Ubuntu" fontSize={labelSize} fontWeight="bold" textAnchor={anchor} dominantBaseline="middle" fill={theme.radar} stroke={theme.radar} strokeWidth={Math.max(3, size * 0.008)} strokeLinejoin="round">{plane.callsign.slice(0, 8)}</text>
        <text x={round(labelX)} y={round(labelY)} fontFamily="Ubuntu" fontSize={labelSize} fontWeight="bold" textAnchor={anchor} dominantBaseline="middle" fill={theme.planeLabel}>{plane.callsign.slice(0, 8)}</text>
      </g>
    })}
  </svg>
}

function themeUi(theme: Theme) {
  const palettes: Record<string, { page: string; card: string; border: string; title: string; route: string; detail: string }> = {
    Midnight: { page: "bg-[#07151a] text-[#e8f5ef]", card: "bg-[#0b2529]", border: "border-[#315d59]", title: "text-[#ffdb9e]", route: "text-[#d8ebe4]", detail: "text-[#9bc9bf]" },
    Ocean: { page: "bg-[#071a2f] text-[#e5f4ff]", card: "bg-[#0c2942]", border: "border-[#356b8b]", title: "text-[#8ce0ff]", route: "text-[#d8efff]", detail: "text-[#a9cfe4]" },
    Forest: { page: "bg-[#102116] text-[#e9f5e8]", card: "bg-[#173324]", border: "border-[#467452]", title: "text-[#d9ee8b]", route: "text-[#e0f1de]", detail: "text-[#b3d3af]" },
    Sunset: { page: "bg-[#2b1520] text-[#fff0e9]", card: "bg-[#40202b]", border: "border-[#89505c]", title: "text-[#ffd08a]", route: "text-[#ffe0d4]", detail: "text-[#e9b9ae]" },
    Plum: { page: "bg-[#21152f] text-[#f3edff]", card: "bg-[#30203f]", border: "border-[#71558e]", title: "text-[#f0b7ff]", route: "text-[#eadfff]", detail: "text-[#c8b7e2]" },
    Paper: { page: "bg-[#f4efe3] text-[#27251f]", card: "bg-[#fffaf0]", border: "border-[#b8ae9b]", title: "text-[#6b4d21]", route: "text-[#353128]", detail: "text-[#605d53]" }
  }
  return palettes[theme.name] || palettes.Midnight
}

function FlightCard({ plane, theme }: { plane: Aircraft; theme: Theme }) {
  const route = plane.origin && plane.destination ? `${plane.origin} to ${plane.destination}` : "Route unavailable"
  const routeLine = plane.country ? `${plane.country} · ${route}` : route
  const detail = `${Math.round(plane.distance)} KM · ${plane.altitudeFt === null ? "ALT —" : `${plane.altitudeFt.toLocaleString()} FT`} · ${plane.speedKts === null ? "SPD —" : `${plane.speedKts} KT`}`
  const ui = themeUi(theme)
  return <div className={`flex min-w-0 flex-col justify-center rounded-xl border px-[1.5vh] py-[1vh] ${ui.card} ${ui.border}`}>
    <div className={`truncate text-[2.35vh] font-bold ${ui.title}`}>{plane.callsign}{plane.airline ? ` · ${plane.airline}` : ""}</div>
    <div className={`truncate text-[1.8vh] ${ui.route}`}>{routeLine}</div>
    <div className={`truncate text-[1.5vh] ${ui.detail}`}>{detail}</div>
  </div>
}

export function get(app: any, context: any) {
  const W = Math.round(context.targetWidth || context.imageWidth || app.frame.width)
  const H = Math.round(context.targetHeight || context.imageHeight || app.frame.height)
  const isLandscape = W > H
  const isUltraWide = isLandscape && W / H > 2.1
  const isNarrowPortrait = !isLandscape && H / W > 2.1
  const latitude = Number(app.config.latitude)
  const longitude = Number(app.config.longitude)
  const radiusKm = Math.max(5, Math.min(250, Number(app.config.radiusKm) || 60))
  const theme = themes[String(app.config.theme || "midnight")] || themes.midnight
  const ui = themeUi(theme)
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) throw new Error("Set a valid latitude and longitude.")
  const north = latitude + radiusKm / kmPerDegreeLat
  const south = latitude - radiusKm / kmPerDegreeLat
  const lonSpan = radiusKm / (kmPerDegreeLat * Math.max(0.2, Math.cos(latitude * Math.PI / 180)))
  let rows: any[] = []
  let failed = false
  try {
    rows = frameos.fetchJson(`https://opensky-network.org/api/states/all?lamin=${south}&lomin=${longitude - lonSpan}&lamax=${north}&lomax=${longitude + lonSpan}`)?.states || []
  } catch (_) {
    failed = true
  }
  const aircraft = rows.map((row) => toAircraft(row, latitude, longitude, radiusKm)).filter(Boolean).sort((a: Aircraft, b: Aircraft) => a.distance - b.distance).slice(0, 35) as Aircraft[]
  const showInfoPanel = app.config.showInfoPanel !== false && app.config.showInfoPanel !== "false"
  const cache = (frameos.recall("routeCache") || {}) as Record<string, any>
  const budget = { left: 8, changed: false }
  const listCount = isUltraWide || isNarrowPortrait ? 10 : isLandscape ? 8 : 4
  const listColumns = (!isLandscape && W < 560) ? 1 : 2
  const listed = showInfoPanel ? aircraft.slice(0, listCount).map((plane) => ({ ...plane, ...routeFor(plane.callsign, cache, budget) })) : []
  if (budget.changed) frameos.remember("routeCache", cache)
  // Whole pixels: the map lines come in the radar's own pixels.
  const radarSize = Math.round(showInfoPanel ? (isLandscape ? Math.min(H - H * 0.035, W * 0.675) : Math.min(W - W * 0.035, H * 0.7)) : Math.min(W - W * 0.07, H - H * 0.07))
  const mapMode = String(app.config.map || "names")
  const townSize = Math.max(10, radarSize * 0.02)
  // An ESP32 holds its canvas and the scene in a few MB: a smaller map there.
  const mapMaxKb = app.frame.embedded ? 40 : 120
  const map = mapMode === "off" ? null : fetchMap(latitude, longitude, radiusKm, radarSize, mapMode === "names", townSize, mapMaxKb)
  if (!showInfoPanel) return <div className={`flex h-full w-full items-center justify-center p-[3.5vh] ${ui.page}`}>
    <div className="aspect-square h-full max-h-full w-full max-w-full"><Radar aircraft={aircraft} radiusKm={radiusKm} size={radarSize} theme={theme} map={map} townSize={townSize} /></div>
  </div>
  return <div className={isLandscape ? `flex h-full w-full flex-row p-[1.6vh] ${ui.page}` : `flex h-full w-full flex-col p-[1.6vh] ${ui.page}`}>
    <section className={isLandscape ? (isUltraWide ? "flex min-h-0 w-[42%] flex-none items-center justify-center" : "flex min-h-0 w-[68%] flex-none items-center justify-center") : "flex min-h-0 flex-1 items-center justify-center"}>
      <div className="aspect-square h-full max-h-full w-full max-w-full"><Radar aircraft={aircraft} radiusKm={radiusKm} size={radarSize} theme={theme} map={map} townSize={townSize} /></div>
    </section>
    <section className={isLandscape ? (isUltraWide ? "grid w-[58%] shrink-0 grid-cols-2 gap-[.8vh] pl-[1vh]" : "grid w-[32%] shrink-0 grid-cols-1 gap-[.8vh] pl-[1vh]") : `grid shrink-0 gap-[.8vh] pt-[1vh] ${listColumns === 1 ? "grid-cols-1" : "grid-cols-2"}`}>
      {listed.map((plane, index) => <FlightCard key={`${plane.callsign}-${index}`} plane={plane} theme={theme} />)}
      {failed ? <div className="col-span-2 text-center text-[1.4vh] text-[#83b9af]">Live flight feed unavailable — will retry</div> : null}
    </section>
  </div>
}
